import re
import sys


def is_sentence_end(sentence_part, terminator):
    terminator_len = len(terminator)
    if terminator_len == 1 and terminator == ".":
        word_before = (
            sentence_part.split()[-1]
            if sentence_part.strip().split()
            else ""
        )
        return word_before.lower() in {"mr", "mrs", "dr", "st"}
    return True


def main():
    text = sys.stdin.read()
    paragraphs = []
    paragraph = []
    for line in text.splitlines():
        stripped_line = line.strip()
        if not stripped_line:
            if paragraph:
                paragraphs.append("\n".join(paragraph))
                paragraph = []
        else:
            paragraph.append(line)
    if paragraph:
        paragraphs.append("\n".join(paragraph))

    words = []
    for paragraph_text in paragraphs:
        sentence_parts = re.split(r"[.!?]+", paragraph_text)
        for sentence_part in sentence_parts:
            words_in_sentence = re.findall(r"[A-Za-z0-9\']+", sentence_part)
            words.extend(words_in_sentence)
            if not words_in_sentence:
                continue
            terminators = re.findall(r"[.!?]+", sentence_part)
            if terminators:
                terminator = terminators[-1]
                if not is_sentence_end(sentence_part, terminator):
                    continue

    print("paragraphs", len(paragraphs))
    print("sentences", sum(1 for p in paragraphs if re.search(r"[.!?]+", p)))
    print("words", len(words))
    if words:
        print("longest", max(words, key=lambda x: len(x)))
    else:
        print("longest", "-")


if __name__ == "__main__":
    main()
